using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static class GridShiftV26Authoring {
 static int materialIndex;
 [MenuItem("GridShift/Objetos editáveis/Preparar cenas e referências")]
 public static void Prepare(){if(EditorApplication.isPlaying)throw new InvalidOperationException("Pare o Play antes de preparar as cenas.");Directory.CreateDirectory("Docs/Validacao26");Directory.CreateDirectory("Assets/Generated/Editable26");
 var models=GridShiftV26Models.Common();var scene=EditorSceneManager.OpenScene("Assets/Scenes/Apartment.unity");var house=UnityEngine.Object.FindFirstObjectByType<GridShiftApartment>();house.Configure();
 foreach(var use in house.GetComponentsInChildren<GridShiftHomeUse>(true))house.AddUse(use.transform,use.kind,use.title,use.localPoint);
 foreach(var bath in house.GetComponentsInChildren<GridShiftHomeBath>(true))bath.AuthorScene();foreach(var tv in house.GetComponentsInChildren<GridShiftHomeTV>(true))tv.AuthorScene();house.GetComponent<GridShiftHomeEnvironment>().AuthorScene();MarkActions(house.gameObject);GridShiftV26Models.Install(scene,models);GridShiftV26UIExport.Attach(scene);PersistMaterials(scene);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
 scene=EditorSceneManager.OpenScene("Assets/Scenes/FactoryInterior.unity");var factory=UnityEngine.Object.FindFirstObjectByType<GridShiftFactoryInterior>();var detail=factory.GetComponent<GridShiftFactoryDetail>();if(detail==null)detail=factory.gameObject.AddComponent<GridShiftFactoryDetail>();detail.AuthorScene();foreach(var attendant in factory.GetComponentsInChildren<GridShiftDepotAttendant>(true))attendant.AuthorScene();foreach(var station in factory.GetComponentsInChildren<GridShiftFactoryStation>(true))station.AuthorScene();MarkActions(factory.gameObject);GridShiftV26Models.Install(scene,models);GridShiftV26UIExport.Attach(scene);PersistMaterials(scene);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);scene=EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");var manager=UnityEngine.Object.FindFirstObjectByType<DeliveryManager>();var operations=manager.GetComponent<GridShiftActiveOperations>();if(operations==null)operations=manager.gameObject.AddComponent<GridShiftActiveOperations>();operations.AuthorScene();var story=manager.GetComponent<GridShiftCampaignWorld>();if(story==null)story=manager.gameObject.AddComponent<GridShiftCampaignWorld>();story.AuthorScene();GridShiftV26Models.Install(scene,models);var lamp=operations.GetComponentInChildren<GridShiftPlayerVan>().GetComponent<GridShiftVehicleLamps>();if(lamp==null)lamp=operations.GetComponentInChildren<GridShiftPlayerVan>().gameObject.AddComponent<GridShiftVehicleLamps>();lamp.AuthorScene();MarkActions(operations.gameObject);GridShiftV26UIExport.Attach(scene);PersistMaterials(scene);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
 scene=EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");GridShiftV26UIExport.Attach(scene);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllLines("Docs/Validacao26/generated-dependencies.txt",AssetDatabase.GetDependencies(new[]{"Assets/Scenes/Apartment.unity","Assets/Scenes/FactoryInterior.unity","Assets/Scenes/SampleScene.unity","Assets/Scenes/MainMenu.unity"},true).Where(p=>p.StartsWith("Assets/Generated/Editable26/")).OrderBy(p=>p));File.WriteAllText("Docs/Validacao26/authoring.txt","Apartment and FactoryInterior authored; runtime bindings reuse scene objects.\n");}
 public static void Batch(){try{Prepare();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void MarkActions(GameObject root){foreach(var a in root.GetComponentsInChildren<GridShiftWorldAction>(true)){a.sceneAuthored=true;if(string.IsNullOrEmpty(a.bindingId))a.bindingId=a.title;if(a.GetComponent<Collider>()==null){if(a.focusSize.sqrMagnitude>0){var c=a.gameObject.AddComponent<BoxCollider>();c.isTrigger=true;c.center=a.focusOffset;c.size=a.focusSize;}else{var c=a.gameObject.AddComponent<SphereCollider>();c.isTrigger=true;c.center=a.focusOffset;c.radius=a.focusRadius;}}}}
 static void PersistMaterials(Scene scene){foreach(var root in scene.GetRootGameObjects())PersistMaterials(root);}
 public static void PersistMaterials(GameObject root){var saved=new Dictionary<Material,Material>();foreach(var r in root.GetComponentsInChildren<Renderer>(true)){var slots=r.sharedMaterials;for(int i=0;i<slots.Length;i++){var m=slots[i];if(m==null||AssetDatabase.Contains(m))continue;if(!saved.TryGetValue(m,out var asset)){asset=UnityEngine.Object.Instantiate(m);asset.name=m.name;string path=AssetDatabase.GenerateUniqueAssetPath("Assets/Generated/Editable26/Material-"+(materialIndex++)+".mat");AssetDatabase.CreateAsset(asset,path);saved[m]=asset;}slots[i]=asset;}r.sharedMaterials=slots;}}
}

